namespace sv_5ac126e24a5c4e33ba96b1d3606a46ee.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@* Step progress indicator bar *@

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var status = GetStepStatus(stepIndex);
        <button class="step @status"
                disabled="@(status == "future")"
                @onclick="() => OnStepClick(stepIndex)"
                aria-current="@(status == "current" ? "step" : null)">
            <span class="step-number">
                @if (status == "completed")
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
        @if (stepIndex < StepNames.Count - 1)
        {
            <span class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "current";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    min-width: 80px;
}

.step:disabled {
    cursor: default;
}

.step-number {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.875rem;
    border: 2px solid #ccc;
    background: white;
    color: #999;
}

.step.current .step-number {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step.completed .step-number {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    color: #999;
    text-align: center;
}

.step.current .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ccc;
    min-width: 20px;
    margin-bottom: 1.25rem;
}

.step-connector.completed {
    background: #198754;
}

.checkmark {
    font-size: 1rem;
}

@* Single work history entry form *@

<div class="work-entry">
    <div class="work-entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" class="form-control" value="@Entry.Company"
                   @onchange="e => UpdateEntry(Entry with { Company = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" class="form-control" value="@Entry.Title"
                   @onchange="e => UpdateEntry(Entry with { Title = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task UpdateEntry(WorkEntryModel updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        await OnEntryChanged.InvokeAsync(updated);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

.work-entry {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.work-entry-header h5 {
    margin: 0;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
    margin-bottom: 0.75rem;
}

.form-group {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.form-group label {
    font-weight: 500;
    font-size: 0.875rem;
}

.form-control {
    padding: 0.375rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.25rem;
    font-size: 1rem;
}

.checkbox-label {
    flex-direction: row !important;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.25rem;
}

@* Single reference entry form *@

<div class="reference-entry">
    <div class="reference-header">
        <h5>Reference @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" class="form-control" value="@Entry.Name"
                   @onchange="e => UpdateEntry(Entry with { Name = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" class="form-control" value="@Entry.Relationship"
                   @onchange="e => UpdateEntry(Entry with { Relationship = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" class="form-control" value="@Entry.Email"
                   @onchange="e => UpdateEntry(Entry with { Email = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" class="form-control" value="@Entry.Phone"
                   @onchange="e => UpdateEntry(Entry with { Phone = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnEntryChanged { get; set; }
