arguments.file_text:
@using sv_5ac126e24a5c4e33ba96b1d3606a46ee.Models

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" class="form-control" value="@FullName"
               @onchange="e => FullName = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" class="form-control" value="@Email"
               @onchange="e => Email = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" class="form-control" value="@Phone"
               @onchange="e => Phone = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea class="form-control" rows="2" value="@Address"
                  @onchange="e => Address = (string?)e.Value ?? string.Empty"></textarea>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!isEmailValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@using static sv_5ac126e24a5c4e33ba96b1d3606a46ee.Components.Pages.Apply.WorkEntryForm

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnInitialized()
    {
        if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntryModel());
        }
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntryModel updated)
    {
        Entries[index] = updated;
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
