    private string? ErrorMessage;

    private void HandleInput(ChangeEventArgs e)
    {
        CoverLetter = (string?)e.Value ?? string.Empty;
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "A cover letter is required.";
            return;
        }

        if (CoverLetter.Length > MaxLength)
        {
            ErrorMessage = $"Cover letter must not exceed {MaxLength} characters.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetter.Trim());
    }
}
