arguments.file_text:
@page "/apply"
@using sv_5ac126e24a5c4e33ba96b1d3606a46ee.Models
@using static sv_5ac126e24a5c4e33ba96b1d3606a46ee.Components.Pages.Apply.WorkEntryForm
@using static sv_5ac126e24a5c4e33ba96b1d3606a46ee.Components.Pages.Apply.ReferenceForm
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              ApplicationService="@ApplicationService"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="() => currentStep--" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="() => currentStep--" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="() => currentStep--" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo!"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        ApplicationService="@ApplicationService"
                        OnBack="() => currentStep--"
                        OnEditStep="GoToStep" />
            break;
    }
</div>

@code {
    private int currentStep;

    // Personal Info state
    private string personalFullName = string.Empty;
    private string personalEmail = string.Empty;
    private string personalPhone = string.Empty;
    private string personalAddress = string.Empty;
    private PersonalInfo? personalInfo;

    // Work History state
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // References state
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Cover Letter state
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }
}

.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 1rem;
}

.step-content {
    background: white;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-content h3 {
    margin-top: 0;
    margin-bottom: 1rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #eee;
}

.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.875rem;
}

.form-control {
    width: 100%;
    padding: 0.375rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.25rem;
    font-size: 1rem;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: 1px solid transparent;
    border-radius: 0.25rem;
    font-size: 1rem;
    cursor: pointer;
    text-decoration: none;
}

.btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

.btn-primary {
    background-color: #0d6efd;
    color: white;
}

.btn-secondary {
    background-color: #6c757d;
    color: white;
}

.btn-success {
    background-color: #198754;
    color: white;
}

.btn-outline-secondary {
    border-color: #6c757d;
    color: #6c757d;
    background: transparent;
}

.btn-outline-danger {
    border-color: #dc3545;
    color: #dc3545;
    background: transparent;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    text-decoration: underline;
    padding: 0;
}

.btn-lg {
    padding: 0.75rem 2rem;
    font-size: 1.125rem;
}

.btn-sm {
    padding: 0.25rem 0.5rem;
    font-size: 0.875rem;
}

.alert {
    padding: 0.75rem 1rem;
    border-radius: 0.25rem;
    margin-bottom: 1rem;
