arguments.new_str:
@* Single work history entry form *@

<div class="work-entry">
    <div class="work-entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" class="form-control" value="@Entry.Company"
                   @onchange="HandleCompanyChange" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" class="form-control" value="@Entry.Title"
                   @onchange="HandleTitleChange" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@FormatDate(Entry.StartDate)"
                   @onchange="HandleStartDateChange" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@FormatNullableDate(Entry.EndDate)"
                   disabled="@IsCurrent"
                   @onchange="HandleEndDateChange" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="HandleCurrentChange" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="HandleDescriptionChange"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private static string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");
    private static string FormatNullableDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? "";

    private Task HandleCompanyChange(ChangeEventArgs e)
        => OnEntryChanged.InvokeAsync(Entry with { Company = (string?)e.Value ?? string.Empty });

    private Task HandleTitleChange(ChangeEventArgs e)
        => OnEntryChanged.InvokeAsync(Entry with { Title = (string?)e.Value ?? string.Empty });

    private Task HandleStartDateChange(ChangeEventArgs e)
    {
        var value = (string?)e.Value;
        var date = string.IsNullOrEmpty(value) ? DateTime.Today : DateTime.Parse(value);
        return OnEntryChanged.InvokeAsync(Entry with { StartDate = date });
    }

    private Task HandleEndDateChange(ChangeEventArgs e)
    {
        var value = (string?)e.Value;
        var endDate = string.IsNullOrEmpty(value) ? (DateTime?)null : DateTime.Parse(value);
        return OnEntryChanged.InvokeAsync(Entry with { EndDate = endDate });
    }

    private Task HandleDescriptionChange(ChangeEventArgs e)
        => OnEntryChanged.InvokeAsync(Entry with { Description = (string?)e.Value ?? string.Empty });

    private Task HandleCurrentChange(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        return OnEntryChanged.InvokeAsync(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }

    public record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

